// Node "Kontext": the complaint mail, the settings and the style guide, and the prompt that asks the AI to read the mail.
const body = $('Reklamation eingegangen').first().json.body || {};
const settings = $('Einstellungen').first().json.data || {};
const style = $('Stilregeln lesen').first().json.data || '';
const mail = {
  message_id: String(body.message_id || ('web-' + Date.now())),
  from_email: String(body.from_email || '').toLowerCase().trim(),
  from_name: String(body.from_name || ''),
  subject: String(body.subject || ''),
  text: String(body.text || '').slice(0, 6000),
  received: new Date().toISOString(),
};
const id = mail.message_id.replace(/[<>]/g, '');
const extractPrompt = [
  'TASK: extract',
  'Du liest Reklamations-E-Mails eines Werkzeug-Großhändlers und gibst NUR ein JSON-Objekt zurück, ohne Text davor oder danach.',
  'Felder:',
  '  order_ref: Auftrags- oder Bestellnummer aus der E-Mail (z. B. "RW-2026-0412" oder "S00002"), sonst null',
  '  product_hint: Produktname oder Artikelnummer, die der Kunde nennt, sonst null',
  '  quantity_affected: betroffene Stückzahl als Zahl, sonst 1',
  '  problem_type: "defekt" | "beschaedigt" | "falsch_geliefert" | "fehlt" | "sonstiges"',
  '  customer_wants: "ersatz" | "gutschrift" | "reparatur" | "unklar"',
  '  urgency: "normal" | "hoch"',
  '  language: "de" | "en"',
  '  formality_used: "Sie" | "du"',
  '  summary: ein Satz auf Deutsch, worum es geht',
  'Erfinde nichts. Was nicht in der E-Mail steht, ist null oder "unklar".',
].join('\n');
const user = `MESSAGE-ID: ${id}\nVon: ${mail.from_name} <${mail.from_email}>\nBetreff: ${mail.subject}\n\n${mail.text}`;
return [{ json: { id, mail, settings, style, extractPrompt: { system: extractPrompt, user } } }];

// One function builds the HTTP request for whichever AI the company chose in the settings.
// Keys come from the environment (.env.local) or, for "odoo", from the AI keys already stored in Odoo.
// Every provider gets the same prompts; only the request format differs (OpenAI, Anthropic or Azure).
const PROVIDERS = {
  mock:      { label: 'Testmodell (offline)', url: 'http://mock-llm:8099/v1', fmt: 'openai', local: true },
  ollama:    { label: 'Ollama (lokal)', url: 'http://host.docker.internal:11434/v1', fmt: 'openai', local: true, model: 'qwen2.5:7b' },
  lmstudio:  { label: 'LM Studio (lokal)', url: 'http://host.docker.internal:1234/v1', fmt: 'openai', local: true },
  openai:    { label: 'OpenAI', url: 'https://api.openai.com/v1', fmt: 'openai', env: 'OPENAI_API_KEY', model: 'gpt-4o-mini' },
  anthropic: { label: 'Anthropic Claude', url: 'https://api.anthropic.com/v1', fmt: 'anthropic', env: 'ANTHROPIC_API_KEY', model: 'claude-haiku-5-5' },
  gemini:    { label: 'Google Gemini', url: 'https://generativelanguage.googleapis.com/v1beta/openai', fmt: 'openai', env: 'GEMINI_API_KEY',
               model: 'gemini-2.5-flash' },
  mistral:   { label: 'Mistral', url: 'https://api.mistral.ai/v1', fmt: 'openai', env: 'MISTRAL_API_KEY', model: 'mistral-small-latest' },
  azure:     { label: 'Azure OpenAI', url: '', fmt: 'azure', env: 'AZURE_OPENAI_API_KEY' },
  custom:    { label: 'Eigener Endpunkt', url: '', fmt: 'openai', env: 'LLM_API_KEY' },
};

// "Wie in Odoo eingerichtet": find an AI key among the Odoo system parameters listed in the settings
function odooAiKey(s) {
  const rows = ($('KI aus Odoo lesen').first().json.result || []).filter(r => r.value);
  const prefer = s.odoo_ai_prefer || 'openai';
  const kind = r => (/openai/i.test(r.key) ? 'openai' : /google|gemini/i.test(r.key) ? 'gemini' : /anthropic|claude/i.test(r.key) ? 'anthropic' : null);
  const found = rows.map(r => ({ provider: kind(r), key: r.value, param: r.key })).filter(r => r.provider);
  return found.find(r => r.provider === prefer) || found[0] || null;
}

function llmRequest(s, system, user, temperature) {
  let p = s.llm_provider || 'mock', key = null, from = null;
  if (p === 'odoo') {
    const hit = odooAiKey(s);
    if (!hit)
      throw new Error(
        'In Odoo ist kein KI-Schlüssel hinterlegt (gesucht: ' + (s.odoo_ai_params || []).join(', ') + '). ' +
          'Bitte in den Einstellungen einen anderen KI-Anbieter wählen.',
      );
    p = hit.provider;
    key = hit.key;
    from = 'Odoo (' + hit.param + ')';
  }
  const P = PROVIDERS[p];
  if (!P) throw new Error('Unbekannter KI-Anbieter: ' + p);
  const base = String(s.llm_url || P.url).replace(/\/+$/, '');
  if (!base) throw new Error('Für ' + P.label + ' fehlt die Adresse (URL) in den Einstellungen.');
  key = key || (P.env ? $env[P.env] || $env.LLM_API_KEY : null) || null;
  if (P.env && !key) throw new Error('Für ' + P.label + ' fehlt der API-Schlüssel ' + P.env + ' in .env.local.');
  const model = (from ? s.odoo_ai_model || P.model : s.llm_model) || P.model || 'local-model';
  let url, body;
  const headers = { 'Content-Type': 'application/json' };
  if (P.fmt === 'anthropic') {
    url = base + '/messages';
    headers['x-api-key'] = key;
    headers['anthropic-version'] = '2023-06-01';
    body = { model, max_tokens: 1500, temperature, system, messages: [{ role: 'user', content: user }] };
  } else {
    url = P.fmt === 'azure'
      ? `${base}/openai/deployments/${encodeURIComponent(model)}/chat/completions?api-version=${s.azure_api_version || '2024-10-21'}`
      : base + '/chat/completions';
    if (key) {
      if (P.fmt === 'azure') headers['api-key'] = key;
      else headers['Authorization'] = 'Bearer ' + key;
    }
    body = { model, temperature, messages: [{ role: 'system', content: system }, { role: 'user', content: user }] };
  }
  return { url, headers, body, provider: p, label: P.label + (from ? ', Schlüssel aus ' + from : ''), model, local: !!P.local };
}

// Node "Lese-Anfrage": the HTTP request for the AI that reads the complaint (llmRequest from shared/llm-request.js).
const ctx = $('Kontext').first().json;
const llm = llmRequest(ctx.settings, ctx.extractPrompt.system, ctx.extractPrompt.user, 0);
return [{ json: { ...ctx, llm } }];

// Reads the text out of an answer in OpenAI format (choices) or Anthropic format (content blocks).
const aiText = j => (j.choices?.[0]?.message?.content ?? (j.content || []).map(b => b.text || '').join('') ?? '');

// Node "KI-Antwort prüfen": checks the AI's reading of the complaint against the allowed values
// and builds the Odoo search for the order (by order number, else by the sender's e-mail).
const ctx = $('Lese-Anfrage').first().json;
const raw = aiText($json) || '';
let ext = {};
try {
  ext = JSON.parse(raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1));
} catch (e) {
  ext = { parse_error: raw.slice(0, 200) };
}
const allowed = {
  problem_type: ['defekt', 'beschaedigt', 'falsch_geliefert', 'fehlt', 'sonstiges'],
  customer_wants: ['ersatz', 'gutschrift', 'reparatur', 'unklar'],
  urgency: ['normal', 'hoch'],
  language: ['de', 'en'],
  formality_used: ['Sie', 'du'],
};
const defaults = { problem_type: 'sonstiges', customer_wants: 'unklar', urgency: 'normal', language: 'de', formality_used: 'Sie' };
for (const [k, vals] of Object.entries(allowed)) if (!vals.includes(ext[k])) ext[k] = defaults[k];
ext.quantity_affected = Math.max(1, parseInt(ext.quantity_affected) || 1);
const ref = ext.order_ref ? String(ext.order_ref).trim() : null;
const domain = ref ? ['|', ['client_order_ref', '=', ref], ['name', '=', ref]] : [['partner_id.email', '=ilike', ctx.mail.from_email]];
return [{ json: { ...ctx, ext, orderDomain: domain } }];

// Fixed complaint rules: which order line is meant, warranty, and which remedy is proposed.
// The AI only fills in what the customer wrote (problem type, wish, product hint); everything here is plain logic.
// The builder puts this file in front of the "Entscheidung" Code node; test/rules.test.mjs tests the same functions.

const DAY_MS = 1000 * 60 * 60 * 24;
const MONTH_DAYS = 30.44;

// The order line the customer means: the product they named, else the only line, else (no hint at all) the first line.
function pickLine(lines, productHint) {
  const hint = (productHint || '').toLowerCase();
  const code = l => (l.name.match(/\[(.*?)\]/) || [])[1]?.toLowerCase() || '###';
  return (
    lines.find(l => hint && (l.name.toLowerCase().includes(hint) || hint.includes(code(l)))) ||
    (lines.length === 1 ? lines[0] : null) ||
    (hint ? null : lines[0])
  );
}

// Months between an Odoo datetime ("2026-11-03 10:00:00", UTC) and now, as a decimal number
const monthsSince = (odooDatetime, now) => (now - new Date(odooDatetime.replace(' ', 'T') + 'Z')) / (DAY_MS * MONTH_DAYS);

// Warranty in months from the settings: business customers (B2B) and private customers (B2C)
const warrantyMonths = (isCompany, s) => (isCompany ? Number(s.warranty_months_b2b || 12) : Number(s.warranty_months_b2c || 24));

// The remedy for a complaint whose order, line and delivery are known.
// Order of the rules: warranty first, then wrong or missing goods, then the customer's wish, then the company default.
function decideRemedy({ months, limit, problemType, customerWants, defaultRemedy }) {
  if (months > limit) return { decision: 'out_of_warranty', reason: `Lieferung vor ${Math.round(months)} Monaten, Gewährleistung ${limit} Monate.` };
  if (['falsch_geliefert', 'fehlt'].includes(problemType)) return { decision: 'replacement', reason: 'Falsche oder fehlende Ware wird nachgeliefert.' };
  if (customerWants === 'gutschrift') return { decision: 'credit', reason: 'Kunde wünscht Gutschrift, innerhalb der Gewährleistung.' };
  if (customerWants === 'ersatz') return { decision: 'replacement', reason: 'Kunde wünscht Ersatz, innerhalb der Gewährleistung.' };
  return { decision: defaultRemedy === 'credit' ? 'credit' : 'replacement', reason: 'Innerhalb der Gewährleistung, Standardlösung laut Einstellungen.' };
}

// Amount for the affected quantity, gross, rounded to cents
const affectedAmount = (line, qty) => Math.round((line.price_total / line.product_uom_qty) * qty * 100) / 100;

// Node "Entscheidung": finds the order line and decides the remedy with the rules in rules/complaint-rules.js,
// then prepares the draft for Odoo (credit note or replacement order).
const c = $('KI-Antwort prüfen').first().json;
const s = c.settings, ext = c.ext;
const result = n => $(n).first().json.result || [];
const order = result('Auftrag suchen')[0] || null;
const lines = order ? result('Positionen lesen') : [];
const picks = order ? result('Lieferung lesen') : [];
const partner = order ? result('Kunde lesen')[0] || {} : {};
const now = new Date();

let decision, reason, line = null, amount = 0, delivered = null, months = null, limit = null;
if (!order) {
  decision = 'need_info';
  reason = 'Kein passender Auftrag gefunden: Auftragsnummer fehlt oder stimmt nicht.';
} else {
  line = pickLine(lines, ext.product_hint);
  delivered = picks.map(p => p.date_done).filter(Boolean).sort()[0] || null;
  if (!line) {
    decision = 'need_info';
    reason = 'Auftrag gefunden, aber unklar, welches Produkt betroffen ist.';
  } else if (!delivered) {
    decision = 'need_info';
    reason = 'Der Auftrag ist laut Odoo noch nicht ausgeliefert.';
  } else {
    amount = affectedAmount(line, Math.min(ext.quantity_affected, line.product_uom_qty));
    months = monthsSince(delivered, now);
    limit = warrantyMonths(partner.is_company, s);
    ({ decision, reason } = decideRemedy({ months, limit, problemType: ext.problem_type, customerWants: ext.customer_wants, defaultRemedy: s.default_remedy }));
  }
}

const qty = line ? Math.min(ext.quantity_affected, line.product_uom_qty) : 0;
const facts = {
  customer: partner.name || c.mail.from_name,
  customer_type: partner.id ? (partner.is_company ? 'Firmenkunde' : 'Privatkunde') : 'unbekannt',
  customer_email: partner.email || c.mail.from_email,
  customer_lang: partner.lang || null,
  order: order ? order.name : null,
  order_ref: order ? order.client_order_ref : ext.order_ref,
  order_date: order ? order.date_order.slice(0, 10) : null,
  delivered: delivered ? delivered.slice(0, 10) : null,
  product: line ? line.name : ext.product_hint,
  quantity: qty,
  amount_eur: amount,
  invoice: order && order.invoice_ids.length ? order.invoice_ids[0] : null,
  months_since_delivery: months ? Math.round(months * 10) / 10 : null,
  warranty_months: limit,
};

// the draft in Odoo: a credit note against the customer's invoice, or a free replacement order
let draft = null;
if (decision === 'credit')
  draft = { model: 'account.move', values: {
    move_type: 'out_refund', partner_id: order.partner_id[0], reversed_entry_id: facts.invoice, invoice_origin: order.name, ref: `Reklamation ${c.id}`,
    invoice_line_ids: [[0, 0, { product_id: line.product_id[0], quantity: qty, price_unit: line.price_unit, tax_ids: [[6, 0, line.tax_id]] }]],
  } };
if (decision === 'replacement')
  draft = { model: 'sale.order', values: {
    partner_id: order.partner_id[0], origin: order.name, client_order_ref: `Ersatz zu ${order.client_order_ref || order.name}`,
    note: `Ersatzlieferung, Reklamation ${c.id}`,
    order_line: [[0, 0, { product_id: line.product_id[0], product_uom_qty: qty, price_unit: 0 }]],
  } };

return [{ json: { ...c, order, decision, reason, facts, draft } }];

