// Node "Antwort-Anfrage": the AI writes the reply to the customer from the decision and the Odoo facts,
// following prompts/EMAIL_STYLE.md and the company settings (llmRequest from shared/llm-request.js).
const c = $('Entscheidung').first().json;
const draftId = $('Entwurf in Odoo anlegen').isExecuted ? $('Entwurf in Odoo anlegen').first().json.result : null;
const s = c.settings;
const lang = s.language === 'auto' ? (c.ext.language === 'en' ? 'en-US' : 'de') : s.language;
const formality = s.formality === 'auto' ? c.ext.formality_used : s.formality;
const what = {
  credit: 'Gutschrift über den genannten Betrag',
  replacement: 'kostenlose Ersatzlieferung',
  need_info: 'Rückfrage: fehlende Angaben anfordern',
  out_of_warranty: 'Ablehnung, weil die Gewährleistung abgelaufen ist; kostenpflichtige Reparatur anbieten',
}[c.decision];
const replySettings = {
  language: lang, formality, tone: s.tone, length: s.length, apology: s.apology,
  closing_de: s.closing_de, closing_en: s.closing_en, signature: s.signature,
};
const system = [
  'TASK: reply',
  'Du schreibst die Antwort-E-Mail des Kundenservice der Rheinmark Handels GmbH auf eine Reklamation.',
  'Halte dich exakt an diesen Stilleitfaden:',
  c.style,
  'Einstellungen für diese E-Mail:',
  JSON.stringify(replySettings),
  s.custom_rules ? 'Zusätzliche Regeln des Unternehmens: ' + s.custom_rules : '',
  'Gib NUR die fertige E-Mail zurück: erste Zeile "Betreff: ..." (bzw. "Subject: ..."), Leerzeile, dann der Text mit Signatur.',
].filter(Boolean).join('\n\n');
const user = [
  `MESSAGE-ID: ${c.id}`,
  `Entscheidung: ${what}`,
  `Begründung (intern): ${c.reason}`,
  `Fakten aus Odoo: ${JSON.stringify(c.facts)}`,
  `Original-E-Mail des Kunden:\nBetreff: ${c.mail.subject}\n${c.mail.text}`,
].join('\n\n');
return [{ json: { ...c, draftId, lang, llm: llmRequest(s, system, user, 0.3) } }];

// Reads the text out of an answer in OpenAI format (choices) or Anthropic format (content blocks).
const aiText = j => (j.choices?.[0]?.message?.content ?? (j.content || []).map(b => b.text || '').join('') ?? '');

// The hard writing rules from prompts/EMAIL_STYLE.md that code can check after the AI has written a reply.
// A reply with a problem is sent back to the AI once ("Stil korrigieren"). test/rules.test.mjs tests the list.
const STYLE_RULES = [
  [/[—–]|\s--\s/, 'Gedankenstrich (— oder –)'],
  [/hope this (email|e-mail) finds you|reaching out|don'?t hesitate|feel free to|i hope this helps|great question/i, 'englische KI-Floskel'],
  [/erreicht Sie wohlbehalten|zögern Sie nicht|ich hoffe, (das|dies) hilft|an uns gewandt haben|jederzeit (gerne )?zur Verfügung/i, 'deutsche KI-Floskel'],
  [/\b(delve|seamless|robust|leverage|elevate|streamline|comprehensive|pivotal|testament)\b/i, 'typisches KI-Wort'],
  [/\b(nahtlos|umfassend|maßgeschneidert|zeitnah)\b/i, 'Füllwort'],
  [/nicht nur .{0,60}, sondern|isn'?t just .{0,40}, it'?s/i, 'Nicht-X-sondern-Y'],
  [/\[[^\]]{2,30}\]|\{[a-z_]+\}/, 'Platzhalter im Text'],
  [/\*\*|^#+\s/m, 'Markdown-Formatierung'],
  [/!.*!/s, 'mehr als ein Ausrufezeichen'],
];

function styleProblems(text) {
  const problems = STYLE_RULES.filter(([re]) => re.test(text)).map(([, label]) => label);
  if (!/^(Betreff|Subject):/i.test(text)) problems.push('Betreffzeile fehlt');
  if (/Mit freundlichen Grüßen[,.]/.test(text)) problems.push('Satzzeichen nach der Grußformel');
  return problems;
}

// Node "Stilprüfung": checks the AI's reply against the hard writing rules (styleProblems from rules/reply-style.js).
const c = $('Antwort-Anfrage').first().json;
const text = (aiText($json) || '').trim();
return [{ json: { ...c, reply: text, problems: styleProblems(text) } }];

