const user = `MESSAGE-ID: ${c.id}\nProbleme: ${c.problems.join('; ')}\n\n${c.reply}`;
return [{ json: { ...c, llm: llmRequest(c.settings, system, user, 0.2) } }];

// Reads the text out of an answer in OpenAI format (choices) or Anthropic format (content blocks).
const aiText = j => (j.choices?.[0]?.message?.content ?? (j.content || []).map(b => b.text || '').join('') ?? '');

// One look for every approval e-mail: light, inline styles, a table shell, no script.
