  '<table class="shell" role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" ' +
  `style="max-width:680px;margin:0 auto;background:#ffffff;border:1px solid ${M.line};border-top:4px solid ${accent};border-radius:4px;border-collapse:separate">\n` +
  `<tr><td class="pad" style="padding:28px 32px 32px;font-family:${M.font};font-size:15px;line-height:1.55;color:${M.ink}">${inner}</td></tr></table></div></body></html>`;

// small line above the headline: "Eingangsrechnung · Supplier"
const kicker = (flow, who) =>
  `<p style="margin:0 0 6px;font-size:13px;line-height:1.4;color:${M.muted}"><span style="font-weight:600;color:${M.ink}">${flow}</span>${who ? ' · ' + who : ''}</p>`;
// the verdict: the same word as in the subject, then one short line that says what it means
const verdict = (t, color) =>
  `<h1 class="verdict" style="margin:0 0 4px;font-size:22px;line-height:1.3;font-weight:600;color:${color || M.ink}">${t}</h1>`;
const subline = t => `<p class="subline" style="margin:0 0 12px;font-size:15px;line-height:1.5;color:${M.ink}">${t}</p>`;
const para = (t, extra) => `<p style="margin:0 0 12px;font-size:15px;line-height:1.55;color:${M.ink};${extra || ''}">${t}</p>`;
const note = t => `<p style="margin:0 0 8px;font-size:13px;line-height:1.5;color:${M.muted}">${t}</p>`;
const section = t => `<h2 style="margin:28px 0 10px;font-size:15px;line-height:1.4;font-weight:600;color:${M.ink}">${t}</h2>`;
const link = (href, t) => `<p style="margin:14px 0 0;font-size:15px"><a href="${href}" style="color:${M.ink};text-decoration:underline">${t}</a></p>`;
const quote = (t, extra) =>
  `<pre style="margin:0;white-space:pre-wrap;word-wrap:break-word;font-family:${M.font};font-size:15px;line-height:1.55;color:${M.ink};` +
  `background:${M.soft};border:1px solid ${M.line};border-radius:4px;padding:16px 20px;${extra || ''}">${t}</pre>`;

// tables: th / td cells, a data table with a header row, and label / value rows ("facts")
const th = (t, right, cls) =>
  `<th${cls ? ` class="${cls}"` : ''} style="padding:8px 12px 8px 0;border-bottom:1px solid ${M.ink};font-size:13px;font-weight:500;` +
  `color:${M.muted};text-align:${right ? 'right' : 'left'};vertical-align:bottom">${t}</th>`;
const td = (t, right, extra, cls) =>
  `<td${cls ? ` class="${cls}"` : ''} style="padding:9px 12px 9px 0;border-bottom:1px solid ${M.line};font-size:14px;` +
  `text-align:${right ? 'right' : 'left'};${right ? 'white-space:nowrap;' : ''}${extra || ''}">${t}</td>`;
const dataTable = (head, rows) =>
  '<table class="data" role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" ' +
  `style="border-collapse:collapse;margin:16px 0 4px;font-family:${M.font};color:${M.ink}">${head ? `<tr>${head}</tr>` : ''}${rows}</table>`;
// rows without a value are left out instead of printing a dash
const facts = (rows, cls) =>
  `<table class="kv${cls ? ' ' + cls : ''}" role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" ` +
  `style="border-collapse:collapse;margin:16px 0 4px;font-family:${M.font};color:${M.ink}">` +
  rows
    .filter(r => r && r[1] !== null && r[1] !== undefined && r[1] !== '')
    .map(([k, v]) =>
      `<tr><td class="k" style="width:150px;padding:9px 12px 9px 0;border-bottom:1px solid ${M.line};font-size:13px;font-weight:500;color:${M.muted};vertical-align:top">${k}</td>` +
      `<td class="v" style="padding:9px 0;border-bottom:1px solid ${M.line};font-size:14px;line-height:1.5;vertical-align:top">${v}</td></tr>`)
    .join('') +
  '</table>';
const decided = rows => section('Wie entschieden wurde') + facts(rows, 'how');

// buttons: [href, label, kind] with kind 'primary' (filled), 'secondary' (outlined) or 'text' (plain link)
const button = ([href, t, kind]) =>
  kind === 'text'
    ? `<a class="btn" href="${href}" style="display:inline-block;margin:0 8px 8px 4px;padding:11px 4px;color:${M.ink};font-family:${M.font};font-size:15px;line-height:1.2;text-decoration:underline">${t}</a>`
    : `<a class="btn" href="${href}" style="display:inline-block;margin:0 8px 8px 0;padding:12px 20px;border:1px solid ${M.ink};border-radius:4px;` +
      `background:${kind === 'primary' ? M.ink : '#ffffff'};color:${kind === 'primary' ? '#ffffff' : M.ink};font-family:${M.font};font-size:15px;font-weight:600;line-height:1.2;text-decoration:none">${t}</a>`;
const buttons = (list, after) =>
  `<div class="actions" style="margin-top:28px">${list.filter(Boolean).map(button).join('')}` +
  (after ? `<p style="margin:10px 0 0;font-size:13px;line-height:1.5;color:${M.muted}">${after}</p>` : '') +
  '</div>';

const deDate = iso => (iso ? String(iso).slice(0, 10).split('-').reverse().join('.') : null);
const groups = s => String(s || '').replace(/\s/g, '').toUpperCase().replace(/(.{4})/g, '$1 ').trim();
// Odoo is linked at the address the person opens in the browser (ODOO_PUBLIC_URL in .env.local, default localhost)
const ODOO_WEB = String($env.ODOO_PUBLIC_URL || 'http://localhost:8069').replace(/\/+$/, '');

// Node "Freigabe-Mail bauen": the approval e-mail to the complaint team. Presentation only: the decision,
// the facts and the reply come from the earlier nodes. Uses the helpers in shared/mail-layout.js.
let c = $('Stilprüfung').first().json;
if ($('Stil korrigieren').isExecuted) {
  const fixed = (aiText($('Stil korrigieren').first().json) || '').trim();
  if (fixed && !fixed.startsWith('NO_FIXTURE')) c = { ...c, reply: fixed, fixed: true };
}
const [first, ...rest] = c.reply.split('\n');
const subject = first.replace(/^(Betreff|Subject):\s*/i, '').trim();
const body = rest.join('\n').replace(/^\s+/, '');
const resume = $execution.resumeUrl + ($execution.resumeUrl.includes('?') ? '&' : '?');
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const money = v => Number(v).toFixed(2).replace('.', ',').replace(/\B(?=(\d{3})+(?!\d))/g, '.') + ' €';
const f = c.facts;

// one word per decision, the same in the subject and the headline, then one short line
const label = { credit: 'Gutschrift', replacement: 'Ersatzlieferung', need_info: 'Rückfrage', out_of_warranty: 'Ablehnung' }[c.decision];
const sub = {
  credit: `Gutschrift über ${money(f.amount_eur)} als Entwurf in Odoo, Antwort an den Kunden ist geschrieben.`,
  replacement: 'Ersatzauftrag als Entwurf in Odoo, Antwort an den Kunden ist geschrieben.',
  need_info: 'Angaben fehlen. Die Rückfrage an den Kunden ist geschrieben.',
  out_of_warranty: 'Außerhalb der Gewährleistung. Die Antwort an den Kunden ist geschrieben.',
}[c.decision];
const accent = { credit: M.ok, replacement: M.ok, need_info: M.neutral, out_of_warranty: M.look }[c.decision];
const odooAction = c.draft && c.draft.model === 'sale.order' ? 'sale.action_quotations' : 'account.action_move_out_refund_type';
const odooLink = c.draftId && c.draft ? `${ODOO_WEB}/odoo/action-${odooAction}/${c.draftId}` : null;

// the facts as a person reads them: labels instead of codes, exact age of the delivery, warranty left
const problemDe = { defekt: 'Defekt', beschaedigt: 'Beschädigt', falsch_geliefert: 'Falsche Ware geliefert', fehlt: 'Ware fehlt', sonstiges: 'Sonstiges' }[c.ext.problem_type] || c.ext.problem_type;
const wishDe = { ersatz: 'Ersatz', gutschrift: 'Gutschrift', reparatur: 'Reparatur', unklar: 'nicht genannt' }[c.ext.customer_wants] || c.ext.customer_wants;
const daysSince = f.delivered ? Math.floor((Date.now() - Date.parse(f.delivered + 'T00:00:00Z')) / 86400000) : null;
const ago = d => (d === null ? '' : d < 1 ? 'heute' : d === 1 ? 'vor 1 Tag' : d < 60 ? `vor ${d} Tagen` : `vor ${Math.round(d / 30.44)} Monaten`);
const left = () => {
  const m = f.warranty_months - f.months_since_delivery;
  if (m >= 2) return `noch ${Math.floor(m)} Monate`;
  if (m >= 1) return 'noch 1 Monat';
  return `noch ${Math.max(0, Math.round(m * 30.44))} Tage`;
};
const product = p => {
  if (!p) return null;
  const code = (String(p).match(/^\[(.*?)\]\s*/) || [])[1];
  const name = String(p).replace(/^\[.*?\]\s*/, '');
  return code && !name.includes(code) ? `${name} (${code})` : name;
};
const muted = t => `<span style="color:${M.muted}">${t}</span>`;
const custType = f.customer_type === 'unbekannt' ? 'nicht in Odoo gefunden' : f.customer_type;
const rows = [
  ['Kunde', `${esc(f.customer)} ${muted('· ' + esc(custType))}`],
  ['Auftrag', f.order_ref || f.order ? esc([f.order_ref, f.order && f.order !== f.order_ref ? `Odoo ${f.order}` : null].filter(Boolean).join(' · ')) : null],
  ['Produkt', f.product ? `${esc(product(f.product))}${f.quantity ? ` · ${f.quantity} Stück` : ''}` : null],
  ['Geliefert', f.delivered ? `${deDate(f.delivered)}${daysSince !== null ? ' ' + muted('· ' + ago(daysSince)) : ''}` : null],
  ['Gewährleistung', f.warranty_months
    ? `${f.warranty_months} Monate (${f.customer_type}) · ${c.decision === 'out_of_warranty' ? `<b style="color:${M.stop}">abgelaufen</b>` : left()}`
    : null],
  ['Betrag', f.amount_eur ? `${money(f.amount_eur)} ${muted('inkl. USt')}` : null],
  ['Problem', esc(problemDe)],
  ['Wunsch des Kunden', esc(wishDe)],
];
const original = String(c.mail.text || '').trim();
const short = original.length > 700 ? original.slice(0, 700).replace(/\s+\S*$/, '') + ' …' : original;
const aiRow = `${esc(c.llm.label)}${c.llm.model && c.llm.model !== 'local-model' ? `, Modell ${esc(c.llm.model)}` : ''} · ` +
  (c.llm.local ? 'lokal, keine Daten nach außen' : 'Cloud: Inhalt der Reklamation wurde an diesen Anbieter übertragen');
const styleRow = c.fixed
  ? 'Erster Entwurf verletzte Stilregeln und wurde einmal automatisch überarbeitet'
  : c.problems.length ? `<span style="color:${M.stop}">Stilhinweise: ${esc(c.problems.join(', '))}</span>` : 'Keine Verstöße gegen die Stilregeln';
const what = {
  credit: 'Freigeben bucht die Gutschrift in Odoo und sendet die Antwort.',
  replacement: 'Freigeben bestätigt den Ersatzauftrag in Odoo und sendet die Antwort.',
  need_info: 'Freigeben sendet die Rückfrage an den Kunden.',
  out_of_warranty: 'Freigeben sendet die Antwort an den Kunden.',
